-- 053. Олжас: «Мен» → «Я» (25.11, на слух: голос читает «Мен» плохо).
begin;
update characters set intro_text = replace(intro_text, '— Мен не знаю ничего.', '— Я не знаю ничего.') where id = 'ea6167fb-4eea-5e08-ae65-e5fce24e6a6c';
update characters set fixed_questions = jsonb_set(fixed_questions, '{3,a}', to_jsonb('"— Чай носил. Хлеб.\nОн со мной через люк разговаривал. Про дочку. Ей двенадцать, говорил.\nНормальный мужик. Не ругался.\nЯ мешок ему на голову... туго не стал. Не смог. Я не зверь."'::json #>> '{}')) where id = 'ea6167fb-4eea-5e08-ae65-e5fce24e6a6c';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R102' then jsonb_set(r, '{text}', to_jsonb('"Олжас читает. Медленно, по слогам.\n— Задушен… — Поднимает глаза и сразу опускает. — Я не знаю. Сартаков какой-то. Я не знаю его.\n(трёт ладони о колени. Больше не говорит)"'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = 'ea6167fb-4eea-5e08-ae65-e5fce24e6a6c';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R104' then jsonb_set(r, '{text}', to_jsonb('"Олжас слушает. На словах «высокий молодой парень» перестаёт дышать.\n— Высоких много. Я не знаю.\n(пауза)\n— Аке туда с покупателями ездит. Он дом продаёт, он там всегда. Бабка старая, ей видится.\n(тихо, в пол)\n— Аке ни при чём. Ни при чём."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = 'ea6167fb-4eea-5e08-ae65-e5fce24e6a6c';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R231' then jsonb_set(r, '{text}', to_jsonb('"Олжас смотрит на фамилию. Пальцы сжимают колени.\n— Шмидт… Я не знаю. Немцы какие-то. — Быстро: — Аке там дом продаёт. Я там не был."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = 'ea6167fb-4eea-5e08-ae65-e5fce24e6a6c';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R306' then jsonb_set(r, '{text}', to_jsonb('"Олжас смотрит в пол.\n— Я не знаю, кто куда ездит. Я на базаре работаю. Грузчик."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = 'ea6167fb-4eea-5e08-ae65-e5fce24e6a6c';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R312' then jsonb_set(r, '{text}', to_jsonb('"Олжас слушает. На словах «звонили из таксофона» сжимает колени.\n— Я не звонил. Какие деньги. — Не поднимает глаз. — У меня телефона нет даже."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = 'ea6167fb-4eea-5e08-ae65-e5fce24e6a6c';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R316' then jsonb_set(r, '{text}', to_jsonb('"Олжас долго молчит.\n— Я не знаю, кому он дом показывал."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = 'ea6167fb-4eea-5e08-ae65-e5fce24e6a6c';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R319' then jsonb_set(r, '{text}', to_jsonb('"— Это их дела. Взрослых. — Олжас смотрит в окно. — Я не знаю."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = 'ea6167fb-4eea-5e08-ae65-e5fce24e6a6c';
commit;
